// ── 807 ──────────────────────────────────────────────
let jungle_camps: [JungleType; 4] = [Rhino(0), Mushroom(1), Bee(3), Stump(2)];

// ── 814~815 : '아직 안 깬 캠프'만 bump 아레나 Vec 으로 모은다 ──
// IR: Vec::from_iter_in( Map<Filter<array::IntoIter<JungleType,4>, C0>, C1>, data.context.pool )
// C0(=closure#0, 815) 는 별도 define(m04.ll:66311) 에 있고 본문은:
//     |camp| !is_cleared(camp, player.info.team, version, rnd, player, data, team_plan, 0, debug)
// C1(=closure#1) 은 캡처 0바이트(ZST)이고 IR 상 원소를 그대로 통과시킨다(항등).
let not_cleared_camps: Vec<JungleType, &Bump> =
    jungle_camps.into_iter()
        .filter(|c| !is_cleared(*c, player.info.team, version, rnd, player, data, team_plan, 0, debug))
        .map(|c| c)
        .collect_in(data.context.pool);

// ── 817~821 : 깰 캠프가 하나도 없다 → 가장 빨리 리젠되는 캠프로 미리 간다 ──
if not_cleared_camps.is_empty() {
    // 키 클로저 C2(=closure#2, 818~819) 캡처 = (game.data, game.vtable, player)
    return jungle_camps.into_iter().min_by_key(|c| {
        let moba = (data.cache.game.vtable[0x40])(data.cache.game.data)  // -> GameMode {tag, payload}
                        .as_moba().unwrap();                              // tag != 0 이면 패닉
        let jr: &JungleRunner = &moba.jungle_runner;                      // MobaMode+0x18
        jr.get_camp_state(player.info.team, *c).next_respawn_tick         // JungleCampState+0x18
    }).unwrap();   // 821. min_by_key 는 동점이면 '먼저 온 것' → 배열 순서 Rhino>Mushroom>Bee>Stump 가 타이브레이크
}

// ── 823 : 내 챔프 엔티티를 캐시에서 찾는다 ──
// player_champion: [[Option<&Entity>;5];2] @ AbstractGameWithCache+0x1e0
if player.info.team >= 2 { panic_bounds_check(team, 2); }
let champ: Option<&Entity> =
    data.cache.player_champion[player.info.team][player.info.position as usize];  // null=None

// ── 824~830 : 챔프가 없다(죽음/미스폰 추정) → 지금 목표 유지, 그것도 없으면 랜덤 ──
if champ.is_none() {
    return match now_camp {
        Some(c) => c,                                   // 825, now_camp != -1
        None    => *jungle_camps.choose(rnd).unwrap(),  // 829, 4개 중 균등 랜덤
    };
    // ⚠랜덤 추첨 대상은 not_cleared_camps 가 아니라 원본 jungle_camps 4개 전부다(IR 상 %12 = 배열 alloca).
}

// ── 832~836 : 챔프가 있다 → 미클리어 캠프 중 '가장 가까운' 것 ──
// 키 클로저 C3(=closure#3, 833~835) 캡처 = (map, player, champ)
let champ = champ.unwrap();
return not_cleared_camps.into_iter().min_by_key(|c| {
    let (cx, cy) = data.context.map.camp_pos(*c, player.info.team == 0);   // 834
    game_core::utils::distance_sq(champ.x, champ.y, cx, cy)                // 835
    // IR 실체: dx = abs_diff(champ.x, cx); dy = abs_diff(champ.y, cy); dx*dx + dy*dy (u64, 제곱거리)
}).unwrap();   // 836. 여기서도 동점이면 not_cleared_camps 의 앞쪽(=jungle_camps 순서)이 이긴다
// ── 838 : 함수 끝 ──
